import os
from typing import Any, Dict, List, Optional

from azure.core.credentials import AzureKeyCredential
from azure.ai.documentintelligence import DocumentIntelligenceClient


def _get_env(name: str) -> str:
    value = os.getenv(name)
    if not value:
        raise ValueError(f"Missing required environment variable: {name}")
    return value


def _as_float(value: Any) -> Optional[float]:
    if value is None:
        return None
    try:
        return float(value)
    except (TypeError, ValueError):
        return None


def _field_content(field: Any) -> Optional[str]:
    if field is None:
        return None
    content = getattr(field, "content", None)
    if content is not None:
        return content
    value_string = getattr(field, "value_string", None)
    if value_string is not None:
        return value_string
    value_currency = getattr(field, "value_currency", None)
    if value_currency is not None:
        amount = getattr(value_currency, "amount", None)
        currency_symbol = getattr(value_currency, "currency_symbol", None)
        currency_code = getattr(value_currency, "currency_code", None)
        if amount is not None:
            if currency_code:
                return f"{amount} {currency_code}"
            if currency_symbol:
                return f"{currency_symbol}{amount}"
            return str(amount)
    value_date = getattr(field, "value_date", None)
    if value_date is not None:
        return str(value_date)
    value_number = getattr(field, "value_number", None)
    if value_number is not None:
        return str(value_number)
    return None


def _field_amount(field: Any) -> Optional[float]:
    if field is None:
        return None
    value_currency = getattr(field, "value_currency", None)
    if value_currency is not None:
        return _as_float(getattr(value_currency, "amount", None))
    value_number = getattr(field, "value_number", None)
    if value_number is not None:
        return _as_float(value_number)
    return None


def _extract_line_items(items_field: Any) -> List[Dict[str, Any]]:
    line_items: List[Dict[str, Any]] = []
    if items_field is None:
        return line_items

    values = getattr(items_field, "value_array", None)
    item_list = getattr(values, "values", None) if values else None
    if not item_list:
        return line_items

    for item in item_list:
        obj = getattr(item, "value_object", None)
        props = getattr(obj, "properties", None) if obj else None
        if not props:
            continue

        description = _field_content(props.get("Description"))
        quantity = _field_amount(props.get("Quantity"))
        unit = _field_content(props.get("Unit"))
        unit_price = _field_amount(props.get("UnitPrice"))
        product_code = _field_content(props.get("ProductCode"))
        amount = _field_amount(props.get("Amount"))
        tax = _field_amount(props.get("Tax"))
        date = _field_content(props.get("Date"))

        line_items.append(
            {
                "description": description,
                "quantity": quantity,
                "unit": unit,
                "unit_price": unit_price,
                "product_code": product_code,
                "amount": amount,
                "tax": tax,
                "date": date,
            }
        )

    return line_items


def extract_invoice_fields(file_path: str) -> Dict[str, Any]:
    endpoint = _get_env("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT")
    key = _get_env("AZURE_DOCUMENT_INTELLIGENCE_KEY")

    client = DocumentIntelligenceClient(
        endpoint=endpoint,
        credential=AzureKeyCredential(key),
    )

    with open(file_path, "rb") as f:
        poller = client.begin_analyze_document(
            model_id="prebuilt-invoice",
            body=f,
        )

    result = poller.result()
    if not result.documents:
        return {
            "vendor": None,
            "date": None,
            "total": None,
            "line_items": [],
        }

    doc = result.documents[0]
    fields = doc.fields or {}

    vendor_name = _field_content(fields.get("VendorName"))
    invoice_date = _field_content(fields.get("InvoiceDate"))
    invoice_total = _field_amount(fields.get("InvoiceTotal"))
    line_items = _extract_line_items(fields.get("Items"))

    return {
        "vendor": vendor_name,
        "date": invoice_date,
        "total": invoice_total,
        "line_items": line_items,
    }
